insert into public.expenses(category,description,amount_cents,paid_at,created_at,actor_id,fuel_event_id) values('fuel','Combustível fictício',200,'2026-10-04T12:00Z','2026-10-04T12:00Z','81000000-0000-0000-0000-000000000001','87000000-0000-0000-0000-000000000001');
