select is(public.financial_summary('2026-10-01','2026-10-31','2026-10-10')->>'paidExpensesCents','30200','compra e combustível entram uma vez no caixa');
select is(public.financial_summary('2026-10-01','2026-10-31','2026-10-10')->>'operatingExpensesCents','200','compra não duplica despesa operacional');
select is(public.financial_summary('2026-10-01','2026-10-31','2026-10-10')->>'managementResultCents','-500','resultado inclui perda e combustível não compra');
select throws_ok($$select public.correct_expense((select id from public.expenses where category='fuel'),null,'Não editar origem',gen_random_uuid())$$,'22023','LINKED_EXPENSE','combustível vinculado não editável');
select throws_ok($$select public.correct_expense((select id from public.expenses where category='purchase'),null,'Não editar origem',gen_random_uuid())$$,'22023','LINKED_EXPENSE','compra vinculada não editável');
