select throws_ok($$select public.get_customer_positions('2026-10-31',now(),'',0,101)$$,'22023','INVALID_INPUT','limite máximo100');
select is(public.reconcile_expense_request('83000000-0000-0000-0000-000000000099')->>'status','closed','tentativa incerta encerrada');
select throws_ok($$select public.record_expense('{"category":"other","description":"Fechada","amountCents":1,"paidAt":"2026-10-04"}','83000000-0000-0000-0000-000000000099')$$,'55000','REQUEST_CLOSED','save atrasado após encerramento bloqueado');
select set_config('request.jwt.claim.sub','81000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.financial_summary('2026-10-01','2026-10-31')$$,'42501','FORBIDDEN','motorista não vê financeiro');
select throws_ok($$select public.dashboard_summary('2026-10-01')$$,'42501','FORBIDDEN','motorista não vê dashboard dona');
select throws_ok($$select public.record_expense('{}',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não cria despesa');
