select throws_ok($$select public.financial_summary('2026-10-01','2026-10-31')$$,'42501',null,'anônimo sem execução de financeiro');
select throws_ok($$select public.dashboard_summary('2026-10-01')$$,'42501',null,'anônimo sem execução do dashboard');
